using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using Timarker_WinUI.Services;using Windows.Storage.Pickers;namespace Timarker_WinUI.Pages;public sealed partial class SettingsPage:Page{private bool _loading=true;public SettingsPage(){InitializeComponent();var s=AppData.Current.Settings;ThemeBox.SelectedItem=ThemeBox.Items.OfType<ComboBoxItem>().First(x=>x.Tag?.ToString()==s.Theme);BackgroundPath.Text=s.BackgroundImagePath;OpacitySlider.Value=s.BackgroundOpacity;QuietSwitch.IsOn=s.QuietHoursEnabled;QuietStart.Time=s.QuietHoursStart;QuietEnd.Time=s.QuietHoursEnd;SnoozeBox.Value=s.DefaultSnoozeMinutes;_loading=false;}private void Save(){if(_loading)return;var s=AppData.Current.Settings;s.Theme=((ComboBoxItem)ThemeBox.SelectedItem).Tag!.ToString()!;s.BackgroundImagePath=BackgroundPath.Text;s.BackgroundOpacity=(int)OpacitySlider.Value;s.QuietHoursEnabled=QuietSwitch.IsOn;s.QuietHoursStart=QuietStart.Time;s.QuietHoursEnd=QuietEnd.Time;s.DefaultSnoozeMinutes=(int)SnoozeBox.Value;AppData.Current.SaveSettings();(App.MainWindow as MainWindow)?.ApplyAppearance();}private void Theme_Changed(object s,SelectionChangedEventArgs e)=>Save();private void Opacity_Changed(object s,Microsoft.UI.Xaml.Controls.Primitives.RangeBaseValueChangedEventArgs e)=>Save();private void Setting_Changed(object s,RoutedEventArgs e)=>Save();private void Time_Changed(TimePicker s,TimePickerSelectedValueChangedEventArgs e)=>Save();private void Number_Changed(NumberBox s,NumberBoxValueChangedEventArgs e)=>Save();private async void PickBackground_Click(object s,RoutedEventArgs e){var p=new FileOpenPicker();p.FileTypeFilter.Add(".png");p.FileTypeFilter.Add(".jpg");p.FileTypeFilter.Add(".jpeg");p.FileTypeFilter.Add(".webp");WinRT.Interop.InitializeWithWindow.Initialize(p,WinRT.Interop.WindowNative.GetWindowHandle(App.MainWindow));var f=await p.PickSingleFileAsync();if(f is null)return;BackgroundPath.Text=f.Path;Save();}private void ClearBackground_Click(object s,RoutedEventArgs e){BackgroundPath.Text="";Save();}}
